using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class TimingHostProbe {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static void Call(object h,string n,params object[] a){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,a);}static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
[STAThread]static int Main(){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);Call(h,"TestBrake",7);int crossing=0;for(int n=1;n<=250;n++){Call(h,"ElectricalCycle");Call(h,"ApplyTestInputs");Call(h,"PneumaticCycle");Call(h,"MotionCycle");Call(h,"RouteInputCycle");float ur=F(mem["TLocParam"],9);if(float.IsNaN(ur)||float.IsInfinity(ur))throw new Exception("Nonfinite UR");if(ur<=4.5f){crossing=n;break;}}double seconds=crossing*.1;if(crossing==0||seconds<15||seconds>20)throw new Exception("RE VA timing failed: "+seconds);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Trainer_VA_timing_candidate_validation.json"),new JavaScriptSerializer().Serialize(new{passed=true,host_ticks=crossing,sim_seconds=seconds,ur_bar=F(mem["TLocParam"],9),scope="Experimental scheduler; VA norm only; not installed",production_installed=false}));Console.WriteLine("PASS VA RE timing="+seconds);return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{h.Close();h.Dispose();}}
}
